export async function execute(args = {}) {
  const buckets = {}
  for (const d of args.dates || []) { const k = String(d).slice(0, 7); buckets[k] = (buckets[k] || 0) + 1 }
  return { buckets }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('buckets', async () => {
  const r = await execute({ dates: ['2026-01-01', '2026-01-02', '2026-02-01'] })
  assert.deepEqual(r.buckets, { '2026-01': 2, '2026-02': 1 })
})
